import{_ as e,o as i,c as n,a5 as a}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"Định nghĩa file test.md","description":"","frontmatter":{},"headers":[],"relativePath":"feature/system-maintenance/definition/test.md","filePath":"feature/system-maintenance/definition/test.md"}'),c={name:"feature/system-maintenance/definition/test.md"};function h(o,t,d,r,s,g){return i(),n("div",null,[...t[0]||(t[0]=[a('<h1 id="đinh-nghia-file-test-md" tabindex="-1">Định nghĩa file <code>test.md</code> <a class="header-anchor" href="#đinh-nghia-file-test-md" aria-label="Permalink to &quot;Định nghĩa file `test.md`&quot;">​</a></h1><h2 id="muc-đich" tabindex="-1">Mục đích <a class="header-anchor" href="#muc-đich" aria-label="Permalink to &quot;Mục đích&quot;">​</a></h2><p><code>test.md</code> trả lời câu hỏi <strong>&quot;Làm sao biết feature này đúng&quot;</strong> — liệt kê test case cụ thể suy ra trực tiếp từ Acceptance Criteria trong <code>spec.md</code>, để verify code chạy đúng trước khi coi FR là Done. Không phải file dump kết quả test tự động chạy (CI report), mà là bảng test case người viết trước, dùng để tự kiểm hoặc code test tự động theo.</p><h2 id="ai-viet-khi-nao-viet" tabindex="-1">Ai viết, khi nào viết <a class="header-anchor" href="#ai-viet-khi-nao-viet" aria-label="Permalink to &quot;Ai viết, khi nào viết&quot;">​</a></h2><p>Dev viết song song hoặc ngay sau khi code — mỗi Acceptance Criteria ở <code>spec.md</code> phải có ít nhất một test case tương ứng ở đây. Không viết test case chung chung không map được về AC nào.</p><h2 id="noi-dung-can-co" tabindex="-1">Nội dung cần có <a class="header-anchor" href="#noi-dung-can-co" aria-label="Permalink to &quot;Nội dung cần có&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Cột</th><th>Nội dung</th></tr></thead><tbody><tr><td>Test case ID</td><td>Ngắn, ví dụ <code>TC-01</code>, <code>TC-02</code></td></tr><tr><td>Mô tả</td><td>Input/điều kiện cụ thể đang test</td></tr><tr><td>AC liên quan</td><td>Trỏ về đúng dòng AC nào trong <code>spec.md</code></td></tr><tr><td>Kết quả mong đợi</td><td>Output/response/behavior đúng phải là gì</td></tr><tr><td>Loại</td><td>Happy path / Edge case / Error case — phải có đủ cả 3 loại, không chỉ test happy path</td></tr><tr><td>Trạng thái</td><td>Pass/Fail/Chưa test — cập nhật thật khi verify</td></tr></tbody></table><p>Bắt buộc bao gồm: mọi Edge Case và Error Handling đã ghi trong <code>spec.md</code> (mục 6, 7) phải xuất hiện thành test case ở đây — nếu spec có ghi edge case mà không có test case tương ứng, coi như chưa xong.</p><h2 id="ranh-gioi-voi-cac-file-khac" tabindex="-1">Ranh giới với các file khác <a class="header-anchor" href="#ranh-gioi-voi-cac-file-khac" aria-label="Permalink to &quot;Ranh giới với các file khác&quot;">​</a></h2><ul><li>Không viết lại nghiệp vụ — mỗi test case chỉ cần trỏ về AC, không copy nguyên văn.</li><li>Không phải checklist công việc (đó là <code>task.md</code>) — đây là bảng kiểm chứng kết quả, viết theo input/output, không viết theo hành động &quot;làm gì&quot;.</li><li>FR chỉ coi là Done khi toàn bộ test case ở đây ở trạng thái Pass — nếu có test Fail mà vẫn đóng FR, phải ghi rõ lý do (known issue, chờ fix sau) ngay tại dòng đó.</li></ul>',10)])])}const m=e(c,[["render",h]]);export{u as __pageData,m as default};
